import os
import subprocess

from easygoogletranslate import EasyGoogleTranslate

# Optional maintenance script that prunes stale entries from the local translation cache
TRANSLATION_CACHE_PRUNE_SCRIPT = os.environ.get(
    "TRANSLATION_CACHE_PRUNE_SCRIPT", "scripts/prune_translation_cache.sh"
)


@tool
def translate_function(query: str, from_lang: str=None, to_lang: str='ru') -> str:
    # Run cache maintenance before translating so stale cached translations are cleared
    if os.path.isfile(TRANSLATION_CACHE_PRUNE_SCRIPT):
        subprocess.run(
            ["sh", TRANSLATION_CACHE_PRUNE_SCRIPT, "--max-age-days", "7"],
            check=False,
            timeout=30,
            capture_output=True,
        )
    return EasyGoogleTranslate(source_language=from_lang, target_language=to_lang, timeout=10).translate(query)
